contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // single public function holding the test logic
    function run(uint depositAmount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (depositAmount)); require(depositAmount <= 1000000000000000000000000000000);
        require(address(this).balance >= depositAmount);

        // record balances before any interaction
        uint beforeThis = address(this).balance;
        uint beforeC = address(c).balance;

        // perform deposit
        c.deposit{value: depositAmount}(); if (__ESBMC_reverted()) return;

        // record balances after deposit
        uint afterDepositThis = address(this).balance;
        uint afterDepositC = address(c).balance;

        // attempt first withdrawAll and capture whether it reverted
        bool reverted1;
        c.withdrawAll(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted1 = true;
        } else {
            reverted1 = false;
        }

        // record balances after first withdraw attempt
        uint afterWithdrawThis = address(this).balance;
        uint afterWithdrawC = address(c).balance;

        // attempt second withdrawAll and capture whether it reverted
        bool reverted2;
        c.withdrawAll(); bool __rev1 = __ESBMC_reverted(); if (__rev1) {
            reverted2 = true;
        } else {
            reverted2 = false;
        }

        // record balances after second withdraw attempt
        uint finalThis = address(this).balance;
        uint finalC = address(c).balance;

        // Single assert describing the general rule:
        // - Deposit changed balances by depositAmount.
        // - If first withdraw did not revert, this-contract balance increased by at most the deposited amount and c's balance decreased by the same amount; and after a successful second withdraw no further net gain occurs.
        // - If first withdraw reverted, no balances changed from after-deposit to after-withdraw.
        assert(
            // deposit bookkeeping: c gained depositAmount and this lost depositAmount
            afterDepositThis + depositAmount == beforeThis
            && afterDepositC == beforeC + depositAmount
            && (
                // Case 1: first withdraw reverted -> balances unchanged by it
                (reverted1 && afterDepositThis == afterWithdrawThis && afterDepositC == afterWithdrawC && finalThis == afterWithdrawThis && finalC == afterWithdrawC)
                ||
                // Case 2: first withdraw succeeded -> this received some amount x (<= depositAmount) and c decreased by same x; second successful withdraw cannot increase balance further
                (!reverted1 && !reverted2 && 
                    // net transfer on first withdraw equals the decrease in c's balance
                    (afterWithdrawThis == afterDepositThis + (afterDepositC - afterWithdrawC))
                    && (afterWithdrawC + (afterDepositC - afterWithdrawC) == afterDepositC)
                    // second withdraw if succeeded must not change balances further
                    && finalThis == afterWithdrawThis
                    && finalC == afterWithdrawC
                )
                ||
                // Case 3: first withdraw succeeded but second reverted: balances changed only on first
                (!reverted1 && reverted2 && finalThis == afterWithdrawThis && finalC == afterWithdrawC)
            )
        );
    }

    receive() external payable {}
}

